-- stray – englische Texte (Teil 30), Schlüssel = deutscher Originaltext
local _, ns = ...
local E = ns.LocaleEN

-- Tooltip (tooltip.lua)
E["Ziel: |cff%s%s|r"] = "Target: |cff%s%s|r"
E["Gegenstands-ID"] = "Item ID"
E["Zauber-ID"] = "Spell ID"
E["Quest-ID"] = "Quest ID"
E["Währungs-ID"] = "Currency ID"
E["NPC-ID"] = "NPC ID"
E["Spielernamen im Tooltip in Klassenfarbe"] = "Class-colored player names in tooltip"
E["Der Name von Spielern im Tooltip erscheint in der Farbe ihrer Klasse. Gegner und NPCs bleiben unverändert."] = "Player names in the tooltip are shown in their class color. Enemies and NPCs stay unchanged."
E["Ziel der Einheit im Tooltip"] = "Unit's target in tooltip"
E["Fügt dem Tooltip eine Zeile „Ziel: Name“ hinzu, wenn die Einheit unter der Maus jemanden anvisiert. Spieler erscheinen in Klassenfarbe, du selbst als „Du“. Im Kampf nur, soweit das Spiel die Werte freigibt."] = "Adds a line \"Target: Name\" to the tooltip when the unit under the mouse is targeting someone. Players appear in class color, you as \"You\". In combat only as far as the game releases the values."
E["Gildenrang im Tooltip"] = "Guild rank in tooltip"
E["Zeigt hinter dem Gildennamen im Spieler-Tooltip zusätzlich den Rang in der Gilde."] = "Also shows the guild rank after the guild name in the player tooltip."
E["Tooltip am Mauszeiger"] = "Tooltip at the mouse cursor"
E["Tooltips von Einheiten und Objekten in der Spielwelt erscheinen neben dem Mauszeiger statt in der Bildschirmecke. Tooltips über Aktionsleisten, Taschen und Fenstern bleiben an ihrem Platz."] = "Tooltips of units and objects in the game world appear next to the mouse cursor instead of the screen corner. Tooltips over action bars, bags and windows stay in place."
E["Tooltip-Größe ändern"] = "Change tooltip size"
E["Skaliert den Haupt-Tooltip des Spiels mit dem Regler darunter. Ausgeschaltet gilt wieder die normale Größe."] = "Scales the game's main tooltip with the slider below. Turned off, the normal size applies again."
E["Tooltip-Größe"] = "Tooltip size"
E["Größe des Tooltips in Prozent (50–150). Standard: 100."] = "Tooltip size in percent (50–150). Default: 100."
E["Erst „Tooltip-Größe ändern“ einschalten (direkt darüber)."] = "Turn on \"Change tooltip size\" first (directly above)."
E["IDs im Tooltip anzeigen"] = "Show IDs in tooltip"
E["Hängt an Tooltips von Gegenständen, Zaubern, Auren, Quests, Währungen und NPCs eine graue Zeile mit der ID an – praktisch zum Nachschlagen oder Kopieren in Datenbanken."] = "Appends a grey line with the ID to tooltips of items, spells, auras, quests, currencies and NPCs – handy for looking up or copying into databases."

-- Charakter (character.lua)
E["Helm anzeigen"] = "Show helm"
E["Umhang anzeigen"] = "Show cloak"
E["Ton"] = "Sound"
E["Gesamtlautstärke"] = "Master volume"
E["Ändert die Hauptlautstärke des Spiels."] = "Changes the game's master volume."
E["Auskleiden"] = "Undress"
E["Wappenrock ab"] = "Remove tabard"
E["Wowhead-Link kopieren"] = "Copy Wowhead link"
E["Quest-ID: %d"] = "Quest ID: %d"
E["Lautstärkeregler im Charakterfenster"] = "Volume slider in the character window"
E["Zeigt oben im Charakterfenster einen Regler für die Gesamtlautstärke des Spiels – ohne die Einstellungen zu öffnen."] = "Shows a slider for the game's master volume at the top of the character window – without opening the settings."
E["Helm- und Umhang-Kästchen im Charakterfenster"] = "Helm and cloak checkboxes in the character window"
E["Zwei Kästchen oben im Charakterfenster schalten die Anzeige von Helm und Umhang an deinem Charakter ein oder aus (wie die Einstellung im Spiel)."] = "Two checkboxes at the top of the character window turn the display of helm and cloak on your character on or off (like the in-game setting)."
E["Anprobe: Auskleiden und Wappenrock ab"] = "Dressing room: Undress and Remove tabard"
E["Fügt dem Anprobe-Fenster zwei Knöpfe hinzu: „Auskleiden“ zieht dem Modell alles aus, „Wappenrock ab“ nur den Wappenrock. Das betrifft nur die Vorschau, nicht deine Ausrüstung."] = "Adds two buttons to the dressing room: \"Undress\" removes everything from the model, \"Remove tabard\" only the tabard. This affects the preview only, not your equipment."
E["Wowhead-Link im Questlog kopieren"] = "Copy Wowhead link in the quest log"
E["Zeigt in den Quest-Details einen Knopf „Wowhead“. Ein Klick öffnet ein Feld mit dem Link zur Quest, den du mit Strg+C kopierst.\nDer Link passt zur Spielversion; die Adresse steht oben in character.lua."] = "Shows a \"Wowhead\" button in the quest details. A click opens a box with the link to the quest, which you copy with Ctrl+C.\nThe link matches the game version; the address is at the top of character.lua."
